/**
 * ORCA maritime reference geometry — baked in, not fetched.
 *
 * International maritime boundary lines and marine protected areas are fixed:
 * a treaty line and a gazetted sanctuary do not change between one request and
 * the next. Serving them from the API meant sending the same ~600 KB of
 * coordinates with every query, so they live here instead and the map draws
 * them immediately, offline, with no round trip.
 *
 * This file is GENERATED. Do not hand-edit — regenerate it from the source
 * geometry in `orca-core/data/geo/`.
 *
 * Sources
 *   boundaries : Marine Regions EEZ v12 (`india_eez_boundaries.geojson`)
 *   protected  : MoEFCC / WDPA protected areas (`india_mpa.geojson`)
 *
 * It replaces a hand-written table in `maritimeBoundaries.ts` whose
 * `AUTHENTIC_IMBL_BOUNDARIES` described the entire India-Sri Lanka boundary
 * with eighteen points.
 *
 * Simplified with Douglas-Peucker and rounded to 4 decimal places
 * (about 11 m):
 *   boundaries  35,495 -> 956 points at 0.0002 deg (~22 m)
 *   protected   67,281 -> 3,414 points at 0.0015 deg (~165 m)
 *
 * Most treaty lines are sparse by nature - a legal boundary is a handful of
 * defined turning points, so those pass through essentially unchanged. Only
 * the detailed India-Bangladesh course (13,117 raw points) is meaningfully
 * reduced.
 *
 * Accurate enough to show where a line is and to warn that it is close. NOT
 * survey-grade, and not a substitute for a chart when deciding whether a
 * position is inside or outside. The authoritative check stays server-side in
 * ORCA's geofence, which reads the unsimplified geometry.
 */

export interface OrcaBoundaryLine {
  name: string;
  lineType: string;
  neighbour: string;
  isOuterLimit: boolean;
  /** [lon, lat] pairs, GeoJSON order. */
  coordinates: [number, number][];
}

export interface OrcaProtectedArea {
  name: string;
  designation: string;
  /** Closed ring of [lon, lat] pairs, GeoJSON order. */
  coordinates: [number, number][];
}

